function premiumIcon(string $name):string{$paths=['compass'=>'<circle cx="12" cy="12" r="9"/><path d="m16 8-2 6-6 2 2-6Z"/>','ticket'=>'<path d="M3 7h18v4a2 2 0 0 0 0 4v4H3v-4a2 2 0 0 0 0-4Z"/><path d="M14 7v3m0 3v2m0 2v2"/>','ship'=>'<path d="M5 12V6h14v6M9 6V3h6v3M3 14l9-4 9 4-3 6H6Z"/><path d="M3 22c2-2 4 2 6 0s4 2 6 0 4 2 6 0"/>','star'=>'<path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9Z"/>','users'=>'<circle cx="9" cy="8" r="3"/><path d="M3 21v-2a6 6 0 0 1 12 0v2M16 5a3 3 0 0 1 0 6m2 5a5 5 0 0 1 3 5"/>','heart'=>'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>','message'=>'<path d="M21 11a8 8 0 0 1-8 8H7l-5 3V11a9 9 0 0 1 19 0Z"/><path d="M7 9h9M7 13h6"/>','grid'=>'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>','chevron'=>'<path d="m9 5 7 7-7 7"/>','close'=>'<path d="m6 6 12 12M6 18 18 6"/>','search'=>'<circle cx="10.5" cy="10.5" r="7"/><path d="m16 16 5 5"/>','mail'=>'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/>','share'=>'<circle cx="18" cy="5" r="3"/><circle cx="6" cy="12" r="3"/><circle cx="18" cy="19" r="3"/><path d="m9 10 6-4M9 14l6 4"/>'];return '<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'.($paths[$name]??'<circle cx="12" cy="12" r="9"/>').'</svg>';}
function sectionTitle(string $eyebrow,string $title,string $copy='',string $link='',string $label='Explore more'):string{return '<div class="p-section-heading"><div><span class="eyebrow"><span></span>'.esc($eyebrow).'</span><h2>'.$title.'</h2>'.($copy?'<p>'.esc($copy).'</p>':'').'</div>'.($link?'<a class="p-link" href="'.esc($link).'">'.esc($label).'<span>'.icon().'</span></a>':'').'</div>';}
function premiumReviews(bool $compact=false):string{$reviews=records('reviews');ob_start();?><section class="p-reviews <?=$compact?'is-compact':''?>"><div class="container"><div class="p-section-heading"><div><span class="eyebrow"><span></span>Moments worth sharing</span><h2>Success stories<br><span>in their own words</span></h2><p>Little moments, lasting memories. A space for stories from our travel community.</p></div><div class="slider-buttons"><button type="button" data-slide-prev="reviews" aria-label="Previous reviews"><?=icon()?></button><button type="button" data-slide-next="reviews" aria-label="Next reviews"><?=icon()?></button></div></div><?php if($reviews):?><div class="review-track" id="reviews" tabindex="0" aria-label="Guest reviews carousel"><?php foreach($reviews as $r):?><article class="review-card"><div class="review-top"><span class="review-stars" aria-label="<?=esc($r['rating'])?> out of 5<?=!empty($r['isSample'])?' sample rating':''?>"><?php for($i=0;$i<5;$i++):?><span class="<?=$i<(int)$r['rating']?'filled':''?>"><?=premiumIcon('star')?></span><?php endfor;?></span><span class="quote-mark" aria-hidden="true">“</span></div><?php if(!empty($r['isSample'])):?><span class="sample-label">Sample review</span><?php endif;?><h3><?=esc($r['title'])?></h3><p>“<?=esc($r['quote'])?>”</p><div class="review-author"><span class="review-avatar"><?=esc(mb_substr($r['author'],0,1))?></span><div><strong><?=esc($r['author'])?></strong><small><?=esc($r['location']??'UAE experience')?></small></div><?php if(!empty($r['source'])):?><a href="<?=esc($r['source'])?>" target="_blank" rel="noopener noreferrer" aria-label="View original review"><?=icon()?></a><?php endif;?></div></article><?php endforeach;?></div><?php else:?><div class="reviews-empty"><h3>Your next story starts here.</h3><p>We’d love to hear about your experience. <a href="/contact">Share your feedback with our team.</a></p></div><?php endif;?></div></section><?php return ob_get_clean();}
function premiumNewsletter():string{ob_start();?><section class="p-newsletter container"><div class="newsletter-art"><span class="outline-circle"></span><?=premiumIcon('compass')?><span>GOOD THINGS<br>ARE ON THE<br><em>horizon.</em></span></div><div class="newsletter-copy"><span class="eyebrow">A little travel inspiration</span><h2>Keep a little adventure<br>in your inbox.</h2><p>Join our list for destination ideas and news from Desert Sky.</p><form id="newsletter-form"><label class="sr-only" for="newsletter-email">Email address</label><div class="newsletter-input"><span><?=premiumIcon('mail')?></span><input id="newsletter-email" name="email" type="email" placeholder="Your email address" required autocomplete="email"><button class="button" type="submit">Count me in <?=icon()?></button></div><label class="newsletter-consent"><input type="checkbox" name="consent" required> I agree to receive travel updates and have read the <a href="/privacy">privacy policy</a>.</label><div class="form-message" role="status"></div></form></div></section><?php return ob_get_clean();}
function premiumHome():void{$s=settings();$tours=records('tours');usort($tours,fn($a,$b)=>(int)($b['featured']??0)<=>(int)($a['featured']??0));ob_start();?><section class="p-hero"><?=photo(['image'=>$s['heroImage'],'imageAlt'=>'Golden dunes in the Dubai desert'],'p-hero-bg',true)?><div class="hero-foreground" aria-hidden="true"><img src="<?=esc($s['heroImage'])?>" alt="" width="1500" height="1000"></div><div class="p-hero-scrim"></div><div class="p-hero-content container"><span class="p-hero-overline"><?=premiumIcon('compass')?> A new sky. A new life.</span><h1><?=esc($s['heroTitle'])?></h1><div class="p-hero-caption"><div><p class="p-hero-subtitle"><?=esc($s['heroAccent']==='the everyday.'?'A world beyond ordinary.':$s['heroAccent'])?></p><p><?=esc($s['heroSummary'])?></p></div><a href="#experiences" class="p-round-explore" aria-label="Explore our experiences"><span>LET’S GO</span><?=icon()?></a></div></div><div class="p-hero-search container"><div class="glass-tabs" role="group" aria-label="Choose an experience type"><button type="button" class="active" data-hero-category=""><?=premiumIcon('compass')?> All experiences</button><button type="button" data-hero-category="Desert adventures"><?=icon('sun')?> Desert safaris</button><button type="button" data-hero-category="City & culture"><?=icon('pin')?> City tours</button><button type="button" data-hero-category="On the water"><?=premiumIcon('ship')?> On the water</button><a href="/hotel-booking"><?=premiumIcon('grid')?> Hotel stays</a></div><form action="/tours" class="glass-search"><input type="hidden" name="category" value=""><label><span><?=icon('pin')?> Where would you like to go?</span><select name="destination"><option value="">All UAE destinations</option><?php foreach(records('locations') as $l):?><option value="<?=esc($l['id'])?>"><?=esc($l['title'])?></option><?php endforeach;?></select></label><label><span><?=premiumIcon('search')?> What’s your kind of adventure?</span><input name="q" placeholder="Safari, city tour, attraction…" aria-label="Search experiences"></label><button class="button button-yellow" type="submit"><?=premiumIcon('search')?> Find my experience</button></form><div class="hero-search-foot"><span><?=icon('check')?> Local knowledge</span><span><?=icon('check')?> Private & family experiences</span><span><?=icon('check')?> Clear prices before booking</span></div></div></section><section class="p-benefits"><div class="container"><?php foreach([['pin','Dubai-based team','A local point of view'],['compass','Made for your kind of day','A little escape or a big adventure'],['shield','Secure online checkout','Payment powered by Stripe'],['message','A real team, right here','Help with the little details']] as [$i,$h,$p]):?><div><span class="benefit-icon"><?=in_array($i,['pin','shield'])?icon($i):premiumIcon($i)?></span><div><h3><?=$h?></h3><p><?=$p?></p></div></div><?php endforeach;?></div></section><section class="section container p-trending"><?=sectionTitle('Find your kind of extraordinary','Trending experiences <span>& best sellers</span>','A city adventure, a desert sunset or a day on the water. Start with a little inspiration.','/tours','View all experiences')?><div class="trending-grid"><?php foreach(array_slice($tours,0,4) as $popular):?><a class="trending-tile" href="<?=esc(pathFor($popular))?>"><?=photo($popular)?><div><span><?=esc(locationName($popular['location']))?></span><h3><?=esc($popular['title'])?></h3><strong><?=price($popular)>0?money(price($popular)):'Request a quote'?></strong></div><span class="trending-arrow"><?=icon()?></span></a><?php endforeach;?></div></section><section class="section container p-destinations"><?=sectionTitle('Find your next favourite place','Experience iconic<br><span>UAE destinations</span>','From the first city view to the last desert sunset, discover a UAE that feels like you.','/tours','See every experience')?><div class="p-destination-grid"><?php foreach(records('locations') as $i=>$l):?><a class="p-destination reveal" href="<?=esc(pathFor($l,'locations'))?>"><?=photo($l)?><span class="destination-index">0<?=$i+1?></span><div><span class="destination-count"><?=count(array_filter($tours,fn($t)=>$t['location']===$l['id']))?> experiences to discover</span><h3><?=esc($l['title'])?></h3><p><?=esc($l['summary'])?></p></div><span class="p-destination-arrow"><?=icon()?></span></a><?php endforeach;?></div></section><section class="p-tours-section section" id="experiences"><div class="container"><?=sectionTitle('Make room for extraordinary','Exclusive recommended<br><span>tours & highlights</span>','Big views. New perspectives. The experiences that turn a trip into your story.','/tours','Explore all tours')?><div class="collection-tabs" role="group" aria-label="Filter featured experiences"><button type="button" class="active" data-collection="">All experiences</button><?php foreach(['Desert adventures','City & culture','Attractions & days out','On the water'] as $c):?><button type="button" data-collection="<?=esc($c)?>"><?=esc($c)?></button><?php endforeach;?></div><div class="home-collection"><?=cards($tours)?></div><div class="section-bottom-link"><a href="/tours" class="button button-outline">There’s more to explore <?=icon()?></a></div></div></section><section class="container p-escape-grid"><a href="/tours?category=Desert%20adventures" class="escape-card escape-desert"><img src="/assets/dubai-dunes-hero.webp" alt="Golden sand dunes in the Dubai desert" width="1200" height="800" loading="lazy"><div><span class="mini-tag">A little further from ordinary</span><h2>Chase sunsets.<br>Find your wild.</h2><span class="button button-yellow">Into the desert <?=icon()?></span></div></a><a href="/tours?category=On%20the%20water" class="escape-card escape-water"><img src="/assets/tours/yacht-private-per-hour.webp" alt="A private yacht experience in Dubai" width="1200" height="800" loading="lazy"><div><span class="mini-tag">A fresh perspective</span><h2>Less rush.<br>More blue.</h2><span class="button button-white">Take to the water <?=icon()?></span></div></a></section><section class="container section p-about"><div class="p-about-collage reveal"><div class="about-photo-main"><img src="/assets/coast.webp" alt="Dubai’s coastline seen from above" width="700" height="1000" loading="lazy"></div><div class="about-photo-small"><img src="/assets/abu-dhabi.webp" alt="The Sheikh Zayed Grand Mosque in Abu Dhabi" width="800" height="700" loading="lazy"></div><span class="about-orbit"><?=premiumIcon('compass')?><span>A new sky.<br>A new life.</span></span></div><div class="p-about-copy"><span class="eyebrow"><span></span>Meet your travel people</span><h2>Thoughtfully planned.<br><span>Beautifully experienced.</span></h2><p>Travel is personal. Some days call for adventure. Others call for an open road, a slower moment, or a view you didn’t see coming.</p><p>We’re Desert Sky Tourism, based in Dubai. We help turn “one day” into a day you’ll remember, with experiences across Dubai, Abu Dhabi and Ras Al Khaimah.</p><div class="p-about-features"><div><?=premiumIcon('compass')?><h3>Your interests, your itinerary</h3><p>Discover something that fits the way you love to travel.</p></div><div><?=premiumIcon('message')?><h3>Local people. Real support.</h3><p>A team to help with your plans, from the first question onward.</p></div></div><a class="button" href="/about">Get to know Desert Sky <?=icon()?></a></div></section><?=premiumReviews()?><section class="section p-why"><div class="container"><?=sectionTitle('Travel with confidence','Why choose <span>Desert Sky?</span>','Thoughtful planning. Local perspectives. More space to enjoy your journey.','','')?><div class="why-grid"><?php foreach([['compass','Local knowledge','Explore the UAE with a team based right here in Dubai.'],['users','Your kind of experience','Private outings, family days and moments shaped around your interests.'],['shield','Clear before you book','Review your selected date, guests, extras and total before payment.'],['message','People, not just a booking','A real team to answer your questions and help with the little details.']] as [$i,$h,$text]):?><article><span><?=premiumIcon($i)?></span><h3><?=$h?></h3><p><?=$text?></p></article><?php endforeach;?></div></div></section><section class="container section p-journal"><?=sectionTitle('Field notes & fresh perspectives','A little inspiration.<br><span>A lot to look forward to.</span>','Useful ideas, thoughtful tips and places that stay with you.','/guides','Visit the travel journal')?><?=journalCards()?></section><section class="container section p-faq-section"><div><span class="eyebrow"><span></span>A little clarity before you go</span><h2>Good questions.<br><span>Better adventures.</span></h2><p>Need something a little more specific? Our team is happy to help you plan.</p><a class="button button-outline" href="/contact">Let’s talk travel <?=premiumIcon('message')?></a></div><div><?php foreach([['How do I book an experience?','Choose a tour with a listed price, select your date and guests, then continue to secure Stripe Checkout. The booking is recorded after successful payment, and our team confirms your tour arrangements separately.'],['Can you help plan a private or family trip?','Yes. Tell us where you are staying, who is travelling and what you would love to do. We can discuss suitable experiences, group arrangements and special requests before you book.'],['Why do some experiences show “Request a quote”?','Prices depend on the experience and the arrangements available. When no current price is listed, contact us for a quote rather than making an unpriced booking.'],['Are transfers and attraction tickets included?','Inclusions vary by tour and ticket option. Check the selected experience and ask our team to confirm transfers, admission, meals and optional activities before payment.'],['What if my travel plans change?','Cancellation and refund conditions depend on the selected experience and supplier. Review the tour conditions and contact our team before paying if you need more detail.']] as $i=>[$q,$a]):?><details class="faq" <?=$i===0?'open':''?>><summary><?=esc($q)?><span>+</span></summary><p><?=esc($a)?></p></details><?php endforeach;?></div></section><?php renderPage('Desert Sky Tourism | UAE Tours & Unforgettable Experiences','Discover Dubai, Abu Dhabi and Ras Al Khaimah with Desert Sky Tourism. Explore private tours, desert safaris, attractions and memorable days out.',ob_get_clean());}
function premiumGallery(array $t):array{static $manifest;if($manifest===null)$manifest=is_file(__DIR__.'/gallery-manifest.json')?json_decode(file_get_contents(__DIR__.'/gallery-manifest.json'),true):[];$images=!empty($t['gallery'])?$t['gallery']:($manifest[$t['id']]??[]);return array_values(array_unique(array_filter(array_merge([$t['image']],$images),fn($s)=>safeImage($s)===$s)));}
function premiumTour(array $t):void{$gallery=premiumGallery($t);$location=locationName($t['location']);ob_start();?><section class="ref-tour-title"><div class="container"><div class="breadcrumbs"><a href="/">Home</a><span>/</span><a href="/tours">Tours</a><span>/</span><a href="/destinations/<?=esc($t['location'])?>"><?=esc($location)?></a></div><span class="p-category-label"><?=esc($t['category'])?></span><h1><?=esc($t['title'])?></h1><p><?=esc($location)?> · <?=esc($t['duration']?:'Your UAE experience')?></p></div></section><div class="container p-tour-layout"><article><section class="p-tour-gallery ref-detail-gallery <?=count($gallery)<3?'gallery-single':''?>" aria-label="Tour photographs"><?php foreach(array_slice($gallery,0,3) as $i=>$src):?><button type="button" class="gallery-photo photo-<?=$i?>" data-gallery-open="<?=$i?>" aria-label="View tour photo <?=$i+1?>"><?=photo(['image'=>$src,'imageAlt'=>$i===0?$t['imageAlt']:$t['title'].' — experience photo '.($i+1)],'',$i===0)?></button><?php endforeach;?><button class="gallery-all" type="button" data-gallery-open="0"><?=premiumIcon('grid')?> View photos <span><?=count($gallery)?></span></button></section><?php if($t['image']==='/assets/tours/al-dhayah-fort.webp'):?><div class="container photo-credit">Photo: <a href="https://commons.wikimedia.org/wiki/File:Dhayah_Fort_of_Ras_Al_Khaimah_(Fort_2).jpg" target="_blank" rel="noopener noreferrer">MoominHussain / Wikimedia Commons</a> · <a href="https://creativecommons.org/licenses/by-sa/4.0/">CC BY-SA 4.0</a> (adapted)</div><?php endif;?><div class="ref-gallery-caption"><span>Get a closer look at your next experience.</span><button type="button" class="button button-outline" data-share><?=premiumIcon('share')?> Share tour</button></div><div class="p-tour-facts"><?php foreach([['clock','Duration',$t['duration']?:'Confirmed with your quote'],['pin','Destination',$location],['users','Experience',($t['pricingMode']??'')==='per_group'?'Private · up to '.$t['capacity'].' guests':'Plan your perfect day'],['ticket','Ticket options',(string)($t['ticketOptions']??1).' available option'.(($t['ticketOptions']??1)>1?'s':'')]] as [$i,$label,$v]):?><div><span><?=in_array($i,['clock','pin'])?icon($i):premiumIcon($i)?></span><div><small><?=$label?></small><strong><?=esc($v)?></strong></div></div><?php endforeach;?></div><nav class="p-tour-tabs" aria-label="Experience sections"><a href="#overview">Overview</a><a href="#highlights">Highlights</a><a href="#details">Inclusions</a><a href="#questions">Good to know</a></nav><section class="p-content-panel" id="overview"><span class="eyebrow"><span></span>Get a little closer</span><h2>The experience</h2><p class="tour-lead"><?=esc($t['summary'])?></p><div class="prose"><?=$t['content']?></div></section><section class="p-content-panel" id="highlights"><span class="eyebrow"><span></span>The moments that matter</span><h2>Your highlights</h2><div class="p-highlight-grid"><?php foreach($t['highlights'] as $i=>$h):?><div><span><?=str_pad((string)($i+1),2,'0',STR_PAD_LEFT)?></span><p><?=esc($h)?></p><?=premiumIcon('compass')?></div><?php endforeach;?></div></section><section class="p-content-panel" id="details"><span class="eyebrow"><span></span>Clear from the start</span><h2>The little details</h2><div class="p-inclusions"><div><span class="inclusion-icon"><?=icon('check')?></span><h3>What’s included</h3><p><?=nl2br(esc($t['inclusions']))?></p></div><div><span class="inclusion-icon exclusion-icon">—</span><h3>Plan for separately</h3><p><?=nl2br(esc($t['exclusions']))?></p></div></div><?php if($t['addons']):?><div class="p-addons"><h3>Make it your own</h3><p>Choose your optional extras when booking.</p><?php foreach($t['addons'] as $a):?><div><span><?=premiumIcon('spark')?><?=esc($a['title'])?></span><strong><?=money($a['price'])?><small> / <?=$a['mode']==='per_person'?'person':'unit'?></small></strong></div><?php endforeach;?></div><?php endif;?></section><section class="p-content-panel" id="questions"><span class="eyebrow"><span></span>Before you set off</span><h2>Good to know</h2><details class="faq" open><summary>Pickup &amp; meeting point<span>+</span></summary><p><?=esc($t['pickup']??'Pickup arrangements and any additional transfer fees are confirmed with your quote before payment.')?></p></details><details class="faq" open><summary>How does booking work?<span>+</span></summary><p><?=price($t)>0?'Choose your preferred date and guests, review your total and pay through secure Stripe Checkout. Your booking appears after payment verification. Our team then confirms the tour arrangements.':'Contact our team for a current quote and availability. An enquiry does not reserve a place. Online checkout becomes available once a bookable price is set.'?></p></details><details class="faq"><summary>What is the cancellation policy?<span>+</span></summary><p><?=esc($t['cancellation'])?></p></details><details class="faq"><summary>What about pickup and special requests?<span>+</span></summary><p>Share your hotel, group size and any access needs before booking. Transfer areas, accessibility and special arrangements vary by experience; our team will confirm what can be arranged.</p></details></section><div class="p-local-help"><span><?=premiumIcon('message')?></span><div><h3>A question makes a great starting point.</h3><p>Ask us about the details that matter to your day.</p></div><a class="button button-white" href="/contact?tour=<?=esc($t['slug'])?>">Talk to our team <?=icon()?></a></div></article><aside><div class="ref-aside-facts"><h3><?=premiumIcon('ticket')?> Tour details</h3><dl><dt>Destination</dt><dd><?=esc($location)?></dd><dt>Duration</dt><dd><?=esc($t['duration']?:'Confirmed with your quote')?></dd><dt>Experience</dt><dd><?=esc($t['category'])?></dd><dt>Travel group</dt><dd><?php if(in_array($t['pricingMode']??'',['per_group','per_hour'])):?>Up to <?=esc($t['capacity'])?> per <?=($t['pricingMode']??'')==='per_hour'?'yacht':'vehicle'?><?php else:?>Group size confirmed with your ticket or quote<?php endif;?></dd><dt>Ticket options</dt><dd><?=esc($t['ticketOptions']??1)?></dd></dl></div><div class="p-booking-card"><span class="booking-kicker"><?=icon('sun')?> Your next great day</span><?php if(price($t)>0):?><span class="price-label">Experience from <?=!empty($t['discountPrice'])?'<del>'.money($t['price']).'</del>':''?></span><div class="tour-price"><?=money(price($t))?><small>per <?=($t['pricingMode']??'')==='per_person'?'person':(($t['pricingMode']??'')==='per_hour'?'hour':'private vehicle')?></small></div><p>Pick your preferred date and guest numbers on the next step.</p><a class="button full" href="/booking?tour=<?=esc($t['slug'])?>">Book this experience <?=icon()?></a><a class="button button-outline full" href="/booking?tour=<?=esc($t['slug'])?>#booking-form"><?=commerceIcon('cart')?> Add to cart</a><span class="secure-note"><?=icon('shield')?> Secure checkout with Stripe</span><?php else:?><h3>Request a Quote</h3><p>Let’s find the current price and the right arrangements for your preferred date.</p><a class="button full" href="/contact?tour=<?=esc($t['slug'])?>">Request a quote <?=icon()?></a><?php endif;?><div class="booking-assurances"><span><?=icon('check')?> Details before you decide</span><span><?=icon('check')?> Support from our Dubai team</span><span><?=icon('check')?> Your extras, your choice</span></div><div class="booking-contact"><span><?=premiumIcon('message')?></span><div><small>Need a little guidance?</small><a href="https://wa.me/<?=preg_replace('/\D/','',settings()['whatsapp'])?>?text=<?=rawurlencode('Hello, I’d like to know more about '.$t['title'])?>" target="_blank" rel="noopener noreferrer">Chat with a local expert ↗</a></div></div></div><div class="tour-destination-mini"><?=photo(getRecord('locations',$t['location'])??['image'=>'/assets/dubai.webp','imageAlt'=>$location.' destination'])?><div><small>There’s more to discover</small><a href="/destinations/<?=esc($t['location'])?>"><?=esc($location)?>, your way <?=icon()?></a></div></div></aside></div><section class="section p-related"><div class="container"><?=sectionTitle('Keep a little room for more','Your next adventure<br><span>could be just around the corner.</span>','','/destinations/'.$t['location'],'More in '.$location)?><?=cards(array_values(array_filter(records('tours'),fn($r)=>$r['location']===$t['location']&&$r['id']!==$t['id'])),3)?></div></section><dialog class="gallery-dialog" aria-label="Tour photo viewer"><div class="gallery-dialog-bar"><span data-gallery-count></span><button type="button" data-gallery-close aria-label="Close photo viewer"><?=premiumIcon('close')?></button></div><button type="button" data-gallery-prev aria-label="Previous photo">←</button><img src="<?=esc($gallery[0])?>" alt="<?=esc($t['title'])?> photo"><button type="button" data-gallery-next aria-label="Next photo">→</button></dialog><script type="application/json" id="gallery-data"><?=json_encode($gallery,JSON_HEX_TAG|JSON_HEX_AMP)?></script><?php renderPage($t['title'].' | Desert Sky Tourism',$t['summary'],ob_get_clean(),$t['seo'],false,$t);}
function premiumListing(?array $loc):void{$selected=$loc['id']??text($_GET['destination']??'',100);$query=text($_GET['q']??'',120);$category=text($_GET['category']??'',100);$tours=array_values(array_filter(records('tours'),fn($t)=>(!$selected||$t['location']===$selected)&&(!$query||stripos($t['title'].' '.$t['summary'],$query)!==false)&&(!$category||$t['category']===$category)));$sort=$_GET['sort']??'featured';if($sort==='price')usort($tours,fn($a,$b)=>(price($a)?:PHP_INT_MAX)<=>(price($b)?:PHP_INT_MAX));elseif($sort==='name')usort($tours,fn($a,$b)=>strcmp($a['title'],$b['title']));else usort($tours,fn($a,$b)=>(int)($b['featured']??0)<=>(int)($a['featured']??0));$title=$loc?$loc['title'].', beyond the expected.':'Find your next extraordinary.';ob_start();echo pageHeader('Your next adventure',$title,$loc['summary']??'Desert horizons, city discoveries and little escapes. Find a day that feels like you.');?><div class="container p-listing-layout"><aside class="p-filter-sidebar"><form id="tour-filters" action="/tours"><div class="filter-title"><?=premiumIcon('search')?><h2>Make it your kind of day.</h2></div><label>Where to?<select name="destination"><option value="">All destinations</option><?php foreach(records('locations') as $l):?><option value="<?=esc($l['id'])?>" <?=$selected===$l['id']?'selected':''?>><?=esc($l['title'])?></option><?php endforeach;?></select></label><label>Experience type<select name="category"><option value="">All experiences</option><?php foreach(array_unique(array_column(records('tours'),'category')) as $c):?><option <?=$category===$c?'selected':''?>><?=esc($c)?></option><?php endforeach;?></select></label><label>Something in mind?<input name="q" value="<?=esc($query)?>" placeholder="Tour or activity name"></label><button class="button full" type="submit">Find my experience <?=icon()?></button><a href="/tours" class="clear-filters">Clear all filters</a></form><div class="filter-help"><?=premiumIcon('message')?><h3>A little help choosing?</h3><p>Tell us what you love. We’ll help you find the right day.</p><a href="/contact">Let’s talk travel <?=icon()?></a></div></aside><div><div class="p-results-toolbar"><div><span class="eyebrow">A good day is waiting</span><h2><?=count($tours)?> experiences<?=($loc?' in '.esc($loc['title']):' to explore')?></h2></div><label class="sort-control"><span>Sort by</span><select name="sort" form="tour-filters" data-sort><option value="featured">Featured first</option><option value="price" <?=$sort==='price'?'selected':''?>>Price: low to high</option><option value="name" <?=$sort==='name'?'selected':''?>>A to Z</option></select></label></div><?php if($selected||$category||$query):?><div class="active-filter-tags"><?php foreach(array_filter([$selected?locationName($selected):'',$category,$query]) as $tag):?><span><?=esc($tag)?></span><?php endforeach;?></div><?php endif;?><?=count($tours)?cards($tours):'<div class="empty p-content-panel"><h2>A different path, perhaps?</h2><p>Try another destination or search term to find your next experience.</p><a href="/tours" class="button">See all experiences</a></div>'?><?php if($loc):?><article class="p-content-panel prose location-copy"><span class="eyebrow">Get to know the destination</span><?=$loc['content']?></article><?php endif;?></div></div><?php renderPage($loc?$loc['title'].' Tours & Experiences | Desert Sky Tourism':'UAE Tours & Experiences | Desert Sky Tourism',$loc['summary']??'Discover tours, attractions and adventures across Dubai, Abu Dhabi and Ras Al Khaimah.',ob_get_clean(),$loc['seo']??[],!empty($_GET),$loc);}
function premiumJournal():void{$posts=records('posts');$first=$posts[0]??null;ob_start();echo pageHeader('The travel journal','For the endlessly curious.','Stories to inspire the next escape. Practical ideas to make it your own.');?><section class="container section p-journal-list"><?php if($first):?><a class="p-featured-story" href="<?=esc(pathFor($first,'posts'))?>"><div><?=photo($first,'',true)?></div><article><span class="eyebrow">Editor’s pick · <?=date('d M Y',strtotime($first['publishedAt']))?></span><h2><?=esc($first['title'])?></h2><p><?=esc($first['summary'])?></p><span class="p-link">Read the story <span><?=icon()?></span></span></article></a><?php endif;?><?=sectionTitle('Ideas for your next chapter','The world looks better<br><span>when you’re curious.</span>')?><?=journalCards(999)?></section><?php renderPage('UAE Travel Journal & Destination Guides | Desert Sky Tourism','Discover travel ideas and practical planning guides for Dubai, Abu Dhabi and Ras Al Khaimah.',ob_get_clean());}
function premiumArticle(array $p):void{$p['kind']='posts';ob_start();?><section class="p-article-intro container"><div class="breadcrumbs"><a href="/">Home</a> / <a href="/guides">Travel journal</a> / Field notes</div><span class="p-category-label">The Desert Sky Journal</span><h1><?=esc($p['title'])?></h1><p><?=esc($p['summary'])?></p><div class="article-byline"><span class="author-mark"><?=premiumIcon('compass')?></span><div><strong>Desert Sky Tourism</strong><small><?=date('d M Y',strtotime($p['publishedAt']))?> <span>·</span> Travel inspiration</small></div><button type="button" class="button button-outline" data-share><?=premiumIcon('share')?> Share story</button></div></section><div class="container p-article-photo"><?=photo($p,'',true)?></div><div class="container p-article-layout"><article class="prose article-body"><?=$p['content']?></article><aside class="article-travel-card"><img src="/assets/dubai-dunes-small.webp" alt="Dubai’s golden desert dunes" width="720" height="480" loading="lazy"><div><span class="eyebrow">Make it more than a daydream</span><h3>Your next chapter is waiting.</h3><p>Find an experience that turns inspiration into a day to remember.</p><a class="button full" href="/tours">Explore experiences <?=icon()?></a></div></aside></div><section class="section container"><?=sectionTitle('Keep your curiosity going','A little more<br><span>for the road ahead.</span>','','/guides','All journal stories')?><?=journalCards()?></section><?php renderPage($p['title'].' | Desert Sky Journal',$p['summary'],ob_get_clean(),$p['seo'],false,$p);}
function premiumInfo(array $p):void{$isAbout=$p['slug']==='about';$isHotel=$p['slug']==='hotel-booking';ob_start();echo pageHeader($isHotel?'Stay a little longer':($isAbout?'Our story':'Desert Sky Tourism'),$p['title'],$p['summary']);if($isAbout||$isHotel):?><section class="container section p-info-layout"><div class="p-info-image"><?=photo($p,'',true)?><span class="info-image-stamp"><?=premiumIcon('compass')?> A new sky.<br>A new life.</span></div><article class="prose p-content-panel"><?=$p['content']?><a class="button" href="<?=$isHotel?'/contact?subject=hotel':'/contact'?>"><?=$isHotel?'Let’s find your stay':'Let’s plan something memorable'?> <?=icon()?></a></article></section><?php if($isAbout):?><section class="p-values"><div class="container"><?=sectionTitle('Our way of travelling','A little more thought.<br><span>A lot more possibility.</span>')?><div><?php foreach([['compass','Travel that fits you','A private escape, a family day out, a different perspective. Start with what matters to you.'],['message','A human connection','A Dubai-based team to discuss the details and help turn your ideas into a plan.'],['heart','Room for the good moments','Choose experiences you can enjoy, with space to be present and take it all in.']] as [$i,$h,$text]):?><article><?=premiumIcon($i)?><h3><?=$h?></h3><p><?=$text?></p></article><?php endforeach;?></div></div></section><?php endif;else:?><section class="container p-policy-layout"><aside><span class="eyebrow">A little peace of mind</span><h3>Clear details.<br>Better journeys.</h3><a href="/terms">Booking terms <?=icon()?></a><a href="/privacy">Privacy policy <?=icon()?></a><a href="/contact">Ask our team <?=icon()?></a></aside><article class="prose p-content-panel"><?=$p['content']?></article></section><?php endif;renderPage($p['title'].' | Desert Sky Tourism',$p['summary'],ob_get_clean(),$p['seo'],false,$p);}
